CREATE OR REPLACE FUNCTION public.audit_finance_document() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF TG_OP = 'DELETE' THEN IF EXISTS(SELECT 1 FROM public.profiles WHERE id=OLD.user_id) THEN INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,previous_data) VALUES(OLD.user_id,'document',OLD.id,TG_OP,to_jsonb(OLD)); END IF; RETURN OLD; ELSIF TG_OP = 'UPDATE' THEN NEW.updated_at=now();INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,previous_data,new_data) VALUES(NEW.user_id,'document',NEW.id,TG_OP,to_jsonb(OLD),to_jsonb(NEW));RETURN NEW; ELSE INSERT INTO public.audit_logs(user_id,entity_type,entity_id,action,new_data) VALUES(NEW.user_id,'document',NEW.id,TG_OP,to_jsonb(NEW));RETURN NEW; END IF; END; $$;